//=============================================================================
// cspell:ignore spypoint spypoints steppoint skippoint going jumping honour

#ifndef CDL2H
#include "CDL2.h"
#endif

#ifdef _WIN32
    #include <conio.h>
#else
    #include <termios.h>
    #include <unistd.h>
    #include <sys/select.h>
#endif

#include <string.h>
#include <signal.h>

#undef RETURNV
#undef RETURN
#define RETURNV(res) return c2TraceExit(res)
#define RETURN {c2TraceExit(TRUE);return;}

#define VAL(aff) {.val=aff}
#define PTR(aff) {.ptr=aff}
#define STR(aff) {.str=aff}

// Special key codes
#define KEY_END 1001
#define KEY_HOME 1002
#define KEY_UP 1003
#define KEY_DOWN 1004
#define KEY_LEFT 1005
#define KEY_RIGHT 1006
#define KEY_ESC 27

/////////////////////////////////////////////////////////////////////////////////
// Types and data structures
/////////////////////////////////////////////////////////////////////////////////
typedef enum { C2_ALG_PREDICATE, C2_ALG_TEST, C2_ALG_ACTION, C2_ALG_FUNCTION } C2AlgType;
typedef enum { C2_AFF_INPUT, C2_AFF_OUTPUT, C2_AFF_TRANSPUT, C2_AFF_STRING } C2AffType;
typedef enum { TRACE_ENTER, TRACE_EXIT, TRACE_FAIL, TRACE_ABORT } TraceExitType;

typedef enum { BLACK = 0, RED = 1, GREEN = 2, YELLOW = 3, BLUE = 4, MAGENTA = 5, CYAN = 6, WHITE = 7, RESET = 8 } AnsiColor;


typedef union { VALUE val; VALUE* ptr; char* str; } C2DataValue;

typedef struct {
   int procInfoIndex;
   C2DataValue*   args;
   VALUE*         locals;
   BOOL           spypoint;
} C2StackFrame;

typedef struct C2ProcInfo {
   char*       container;
   char*       name;
   C2AlgType   type;
   int         nargs;
   char**      argnames;
   C2AffType*  affTypes;
   int         nlocals;
   char**      localnames;
   char*       code;
   BOOL        spypoint;
   BOOL        steppoint;
} C2ProcInfo;

typedef struct C2VarInfo {
   char*    container;
   char*    name;
   VALUE*   value;
} C2VarInfo;
typedef struct C2ListInfo {
   char*    container;
   char*    name;
   VALUE*   value;
   int      lwb;
   int      upb;
} C2ListInfo;

typedef struct C2DebugInfo {
   int         procCount;
   C2ProcInfo* procs;
   int         varCount;
   C2VarInfo*  vars;
   int         listCount;
   C2ListInfo* lists;
} C2DebugInfo;

/////////////////////////////////////////////////////////////////////////////////
// Globals
/////////////////////////////////////////////////////////////////////////////////
C2DebugInfo* c2DebugInfo;

#define CALL_STACK_MAX_DEPTH 10000
C2StackFrame C2Stack[CALL_STACK_MAX_DEPTH];
int C2SP = -1;

BOOL C2HonorSpyPoints = FALSE;      // Whther to honour spy points while skipping.
int C2Skippoint= -1;                // The index of the stack frame we are skipping to (used to know when to stop skipping)
BOOL C2TraceWhileJumping = FALSE;   // Used to show trace output for intermediate calls while jumping or ...
BOOL C2Jumping = FALSE;             // Jumping means run until the next spy point
BOOL C2Going = FALSE;               // Going means run without further debugging
BOOL C2StepOverSuccess = TRUE;      // Whether to step over the next exit
BOOL C2StepOverFailure = TRUE;      // Whether to step over the next fail


/////////////////////////////////////////////////////////////////////////////////
// Forward declarations
/////////////////////////////////////////////////////////////////////////////////
void c2PrintStackFrame(int depth, BOOL indent, char* marker, BOOL newline, TraceExitType type);
void c2TraceEnter();
BOOL c2TraceExit(int v);
void c2TraceExitAbort();
void c2traceREPL(int depth,TraceExitType type);
void c2PrintAff(int depth,int i, TraceExitType type);
void c2Backtrace();
C2ProcInfo* c2FindProc(char* name);
C2VarInfo* c2FindVar(char* name);
C2ListInfo* c2FindList(char* list);
BOOL c2SetSpyPoint(char* procName, BOOL set);

BOOL c2StartsWith(char* str, char* prefix);
BOOL c2MatchName(char* name1, char* name2);
char* c2RemoveBlanks(char* str);
BOOL c2IsemptyOrWhitespace(char* str);
void c2SignalHandler(int sig);
void c2InitTrace();
void c2Exit(int code);
char * c2ReadLine();
char c2_getch();
char* ansi_fg(AnsiColor color);
char* ansi_bg(AnsiColor color);



/////////////////////////////////////////////////////////////////////////////////
// Redefine exit() so all code below shows backtraces on errors
/////////////////////////////////////////////////////////////////////////////////
#define exit(code) c2Exit(code)

/////////////////////////////////////////////////////////////////////////////////
// Implementation
/////////////////////////////////////////////////////////////////////////////////

char* c2AlgType(int depth) {
   switch (c2DebugInfo->procs[C2Stack[depth].procInfoIndex].type) {
      case C2_ALG_PREDICATE: return "PREDICATE";
      case C2_ALG_TEST: return "TEST";
      case C2_ALG_ACTION: return "ACTION";
      case C2_ALG_FUNCTION: return "FUNCTION";
      default: return "UNKNOWN";
   }
}  

void c2push_callstack_frame(int procIndex,C2DataValue args[],VALUE* locals) {
   if (C2SP >= CALL_STACK_MAX_DEPTH-1) {
      fprintf(stderr, "Call stack overflow\n");
      exit(1);
   }

   C2SP++;
   C2Stack[C2SP].procInfoIndex = procIndex;
   C2Stack[C2SP].args = args;
   C2Stack[C2SP].locals = locals;
   C2Stack[C2SP].spypoint = FALSE;
}

void c2pop_callstack_frame() {
   if (C2SP < 0) {
      fprintf(stderr, "Call stack underflow\n");
      exit(1);
   }
   C2SP--;
}

BOOL c2SetSpyPoint(char* procName, BOOL set) {
   C2ProcInfo* proc = c2FindProc(procName);
   if (proc != NULL) {
      proc->spypoint = set;
      return TRUE;
   } else {
      return FALSE;
   }
}
   
#define ENTER_MARKER ">"
#define SUCCEED_MARKER "+"
#define FAIL_MARKER "-"
#define NO_MARKER ""

char * C2Marker(TraceExitType type) {
   static char buffer[8];
   
   switch (type) {
   case TRACE_ENTER:   sprintf(buffer, "%s%s", ansi_fg(CYAN), ENTER_MARKER); break;
      case TRACE_EXIT: sprintf(buffer, "%s%s", ansi_fg(GREEN), SUCCEED_MARKER); break;
      case TRACE_FAIL: sprintf(buffer, "%s%s", ansi_fg(RED), FAIL_MARKER); break;
      default: return NO_MARKER;
   }
   return buffer;
}

void c2Backtrace() {
   fprintf(stderr, "\n===== Stack backtrace (most recent call last):\n");
   for (int i = C2SP - 1; i >= 0; i--) {
      c2PrintStackFrame(i,FALSE,NO_MARKER,TRUE,TRACE_EXIT);
   }
   fprintf(stderr, "===== Backtrace ends\n");
}   
   
void c2PrintStackFrame(int depth,BOOL indent, char* marker,BOOL newline,TraceExitType type) {
   C2StackFrame frame = C2Stack[depth];
   C2ProcInfo procInfo = c2DebugInfo->procs[frame.procInfoIndex];
   static char indentation_buffer[256];
   char * indentation = "";
   if (indent) {
      sprintf(indentation_buffer, "%*s", depth, "");
      indentation = indentation_buffer;
   }
   if (!newline) fprintf(stderr,"\n"); // Print a newline before the stack frame when used as debugger prompt
   fprintf(stderr, "%s%s%s %s",indentation,marker,c2AlgType(depth),procInfo.name);
   if (type != TRACE_FAIL) for (int i = 0; i < procInfo.nargs; i++) c2PrintAff(depth, i,type);
   fprintf(stderr,"%s%s", ansi_fg(RESET), newline ? "\n" : ": ");
}

void c2PrintAff(int depth,int i, TraceExitType type) {
   C2StackFrame frame = C2Stack[depth];
   C2ProcInfo procInfo = c2DebugInfo->procs[frame.procInfoIndex];
   char* name = procInfo.argnames[i];
   switch (procInfo.affTypes[i]) {
      case C2_AFF_INPUT:    fprintf(stderr, "+>%s=%ld", name,frame.args[i].val); break;
      case C2_AFF_OUTPUT:   
         if (type == TRACE_ENTER) {
            fprintf(stderr, "+%s>",name);
         } else {
            fprintf(stderr, "+%s>=%ld",name,*frame.args[i].ptr);
         }
         break;
      case C2_AFF_TRANSPUT: fprintf(stderr, "+>%s>=%ld",name,*frame.args[i].ptr); break;
      case C2_AFF_STRING:   fprintf(stderr, "*%s=%s",   name,frame.args[i].str); break;
      default: fprintf(stderr, "+??");
   }
}

// Called after c2_push_callstack_frame so call information is on the stack.
BOOL firstEntry = TRUE;
void c2TraceEnter() {
   if (firstEntry) {
      c2InitTrace();  // Initialize signal handlers on first entry
      fprintf(stderr, "CDL2 debugger v1.0, h for help\n");
      firstEntry = FALSE;
   }
   if (C2Going) {
      // If we are going, just return without showing trace output
      return;
   }
   if (C2Skippoint >=0) {
      // We are skipping
      if (C2HonorSpyPoints && C2Stack[C2SP].spypoint) {
         // Skipping, but we are honouring spy points and this is a spy point: need to stop
         C2Skippoint = -1; // Stop skipping when we hit a spy point
         C2HonorSpyPoints= FALSE; // Because spypoint honouring applies only to skipping and is irrelevant otherwise.
      } else {
         // Otherwise, just continue without stopping
         return; 
      }
   } else if (C2Stack[C2SP].spypoint) {
      // We are not skipping, and this is a spy point.
      C2HonorSpyPoints= FALSE; // Should already be false as we are not skipping.
      C2Jumping = FALSE; // Because we are stopping at the spy point, we are no longer jumping.
      return; 
   }
   if (C2Jumping) {
      // We are jumping, but this is not a spy point.
      return;
   }
   // Not skipping
   c2traceREPL(C2SP, TRACE_ENTER);
}
// Called without popping the stack, so it must do it.
BOOL c2TraceExit(int v) {
   if (C2Going) {
      // If we are going, just return without showing trace output
   } else if (C2Skippoint >=0) {
      // We are skipping
      if (C2Skippoint == C2SP) {
         // We have reached the point we wanted to skip to, so stop skipping
         C2Skippoint = -1;
         C2HonorSpyPoints = FALSE; // Because spypoint honouring applies only to skipping and is irrelevant otherwise.
         c2traceREPL(C2SP, v==FALSE ? TRACE_FAIL : TRACE_EXIT);
      }
   //} else if (C2Stack[C2SP].spypoint) {
      // Do spypoints apply to exits? for now, no.
   } else if (v && C2StepOverSuccess) {
      c2PrintStackFrame(C2SP, TRUE, C2Marker(TRACE_EXIT), FALSE, TRACE_EXIT);
   } else if (!v && C2StepOverFailure) {
      c2PrintStackFrame(C2SP, FALSE, C2Marker(TRACE_FAIL), FALSE, TRACE_FAIL);
   } else if (!C2Jumping) {
      // We are not jumping, so stop
      c2traceREPL(C2SP, v==FALSE ? TRACE_FAIL : TRACE_EXIT);
   } else {
      // We are stepping over, but this exit does not match our criteria to step over, so stop
      c2traceREPL(C2SP, v==FALSE ? TRACE_FAIL : TRACE_EXIT);
   }
   c2pop_callstack_frame();
   return v;
}
// Called for the abort operator
void c2TraceExitAbort() {
   fprintf(stderr, "Abort operator reached\n");
   c2Backtrace();
   exit(1);
}

void c2traceREPL(int depth,TraceExitType type) {
   c2PrintStackFrame(depth,TRUE,C2Marker(type),FALSE,type);
   char command = c2_getch();
   fprintf(stderr, "%s%c%s",ansi_fg(YELLOW),command, ansi_fg(RESET));
   switch (command) {
      case 'h':
         fprintf(stderr, "\n%sCommands:\n", ansi_fg(BLUE));
         fprintf(stderr, "  > ENTER - continue until the next trace point (step into)\n");
         fprintf(stderr, "  s TAB   - continue to the exit of the current call (step over)\n");
         fprintf(stderr, "  j SPC   - continue until the next spy point\n");
         fprintf(stderr, "  g END   - continue until the end\n");
         fprintf(stderr, "  b       - show a backtrace of the call stack\n");
         fprintf(stderr, "  +       - set a spy point, enter the procedure name\n");
         fprintf(stderr, "            with argument +/- stop at that exit\n");
         fprintf(stderr, "  -       - clear a spy point, enter the procedure name\n");
         fprintf(stderr, "            with argument +/- don't stop at that exit\n");

         fprintf(stderr, "  q ESC   - quit the program%s\n", ansi_fg(RESET));
         c2traceREPL(depth,type); // After showing help, ask for command again
         break;
      case '+':
      case '-':
         fprintf(stderr, "%s ", ansi_fg(YELLOW));
         char* arg = c2ReadLine();
         fprintf(stderr, "%s", ansi_fg(RESET));
         if (arg[0] == '+') {
            C2StepOverSuccess = command == '-';
            fprintf(stderr, "Will %s stop at success ports\n", C2StepOverSuccess ? "not" : "");
         } else if(arg[0] == '-') {
            C2StepOverFailure = command == '-';
            fprintf(stderr, "Will %s stop at failure ports\n", C2StepOverFailure ? "not" : "");
         } else if (c2IsemptyOrWhitespace(arg)) {
            fprintf(stderr, "Procedure name cannot be empty\n");
         } else if (c2SetSpyPoint(arg, command == '+')) {
            fprintf(stderr, "Spy point %s %s\n", command == '+' ? "set on" : "cleared from", arg);
         } else {
            fprintf(stderr, "No such procedure %s\n", arg);
         }
         c2traceREPL(depth,type); // After setting spy point, ask for command again
         break;
      case '>':
      case '\r':
         if (command == '>') fprintf(stderr, "\n");
         break;
      case KEY_END:
      case 'g':
         fprintf(stderr, "\n");
         C2Going = TRUE;
         break;
      case ' ':
      case 'j':
         fprintf(stderr, "\n");
         C2Jumping = TRUE;
         break;
      case '\t':
      case 's':
         fprintf(stderr, "\n");
         if (type == TRACE_ENTER) {
            C2Skippoint = depth; // Skip until we return to the current stack frame
         }
         break;
      case 'b':
         fprintf(stderr, "\n");
         c2Backtrace();
         c2traceREPL(depth,type); // After showing backtrace, ask for command again
         break;
      case KEY_ESC:
      case 'q':
         fprintf(stderr, "\nQuitting program.\n");
         exit(0);
         break;
      default:
         fprintf(stderr, "\nInvalid command. enter 'h' for help.\n");
         c2traceREPL(depth,type); // After invalid command, ask for command again
         break;
   }
}

/////////////////////////////////////////////////////////////////////////////////////
// Utility functions
/////////////////////////////////////////////////////////////////////////////////////

// Name extractor functions for generic search
char* c2GetProcName(int index) { return c2DebugInfo->procs[index].name; }
char* c2GetVarName(int index) { return c2DebugInfo->vars[index].name; }
char* c2GetListName(int index) { return c2DebugInfo->lists[index].name; }

// Generic binary search function
int c2GenericFind(char* name, int count, char* (*getNameFunc)(int index)) {
   int left = 0;
   int right = count - 1;

   while (left <= right) {
      int mid = (left + right) / 2;
      char* clean_name = c2RemoveBlanks(name);
      char* clean_target = c2RemoveBlanks(getNameFunc(mid));
      int cmp = strcmp(clean_name, clean_target);

      if (cmp == 0 || c2StartsWith(clean_target, clean_name)) {
         free(clean_name);
         free(clean_target);
         return mid;
      }
      else if (cmp < 0) {
         right = mid - 1;
      }
      else {
         left = mid + 1;
      }
      free(clean_name);
      free(clean_target);
   }
   return -1;
}

C2ProcInfo* c2FindProc(char* name) {
   int index = c2GenericFind(name, c2DebugInfo->procCount, c2GetProcName);
   return index >= 0 ? &c2DebugInfo->procs[index] : NULL;
}

C2VarInfo* c2FindVar(char* name) {
   int index = c2GenericFind(name, c2DebugInfo->varCount, c2GetVarName);
   return index >= 0 ? &c2DebugInfo->vars[index] : NULL;
}

C2ListInfo* c2FindList(char* name) {
   int index = c2GenericFind(name, c2DebugInfo->listCount, c2GetListName);
   return index >= 0 ? &c2DebugInfo->lists[index] : NULL;
}

BOOL c2StartsWith(char* str, char* prefix) {
   while (*prefix != '\0') {
      if (*str != *prefix) {
         return FALSE;
      }
      str++;
      prefix++;
   }
   return TRUE;
}

BOOL c2MatchName(char* name1, char* name2) {
   char* clean1 = c2RemoveBlanks(name1);
   char* clean2 = c2RemoveBlanks(name2);
   BOOL result = c2StartsWith(clean1, clean2);
   free(clean1);
   free(clean2);
   return result;
}

char* c2RemoveBlanks(char* str) {
   // First pass: count non-blank characters
   int count = 0;
   for (char* src = str; *src != '\0'; src++) {
      if (*src != ' ') count++;
   }

   // Allocate exactly what we need
   char* result = (char*)malloc(count + 1);
   if (result == NULL) {
      return NULL; // Memory allocation failed
   }

   // Second pass: copy non-blank characters
   char* dst = result;
   for (char* src = str; *src != '\0'; src++) {
      if (*src != ' ') *dst++ = *src;
   }
   *dst = '\0';
   return result;
}

BOOL c2IsemptyOrWhitespace(char* str) {
   for (char* p = str; *p != '\0'; p++) {
      if (*p != ' ' && *p != '\t' && *p != '\n' && *p != '\r') {
         return FALSE;
      }
   }
   return TRUE;
}

// Read line until Enter
char* c2ReadLine() {
   static char buffer[256];
   int i = 0;
   int ch;
   while (i < 255 && (ch = getchar()) != '\n' && ch != '\r' && ch != EOF) {
      buffer[i++] = ch;
   }
   buffer[i] = '\0';
   return buffer;
}

// Cross-platform immediate character input
char c2_getch() {
#ifdef _WIN32
   return _getch();
#else
   struct termios oldattr, newattr;
   char ch;
   tcgetattr(STDIN_FILENO, &oldattr);
   newattr = oldattr;
   newattr.c_lflag &= ~(ICANON | ECHO);
   tcsetattr(STDIN_FILENO, TCSANOW, &newattr);
   ch = getchar();
   tcsetattr(STDIN_FILENO, TCSANOW, &oldattr);
   return ch;
#endif
}

// Cross-platform special key detection
int c2_get_special_key() {
#ifdef _WIN32
   int ch = _getch();
   if (ch == 224) { // Extended key prefix on Windows
      ch = _getch();
      switch (ch) {
      case 79: return KEY_END;     // END key
      case 71: return KEY_HOME;    // HOME key
      case 72: return KEY_UP;      // UP arrow
      case 80: return KEY_DOWN;    // DOWN arrow
      case 75: return KEY_LEFT;    // LEFT arrow
      case 77: return KEY_RIGHT;   // RIGHT arrow
      }
   }
   return ch; // Regular character
#else
   struct termios oldattr, newattr;
   int ch;
   tcgetattr(STDIN_FILENO, &oldattr);
   newattr = oldattr;
   newattr.c_lflag &= ~(ICANON | ECHO);
   tcsetattr(STDIN_FILENO, TCSANOW, &newattr);

   ch = getchar();
   if (ch == 27) { // ESC sequence
      // Set a short timeout to check if more characters are coming
      fd_set readfds;
      struct timeval timeout;
      FD_ZERO(&readfds);
      FD_SET(STDIN_FILENO, &readfds);
      timeout.tv_sec = 0;
      timeout.tv_usec = 100000; // 100ms timeout

      if (select(STDIN_FILENO + 1, &readfds, NULL, NULL, &timeout) > 0) {
         // More characters available - it's an escape sequence
         ch = getchar();
         if (ch == '[') {
            ch = getchar();
            switch (ch) {
            case 'F':
               tcsetattr(STDIN_FILENO, TCSANOW, &oldattr);
               return KEY_END;    // END key
            case 'H':
               tcsetattr(STDIN_FILENO, TCSANOW, &oldattr);
               return KEY_HOME;   // HOME key  
            case 'A':
               tcsetattr(STDIN_FILENO, TCSANOW, &oldattr);
               return KEY_UP;     // UP arrow
            case 'B':
               tcsetattr(STDIN_FILENO, TCSANOW, &oldattr);
               return KEY_DOWN;   // DOWN arrow
            case 'D':
               tcsetattr(STDIN_FILENO, TCSANOW, &oldattr);
               return KEY_LEFT;   // LEFT arrow
            case 'C':
               tcsetattr(STDIN_FILENO, TCSANOW, &oldattr);
               return KEY_RIGHT;  // RIGHT arrow
            case '4':
               if (select(STDIN_FILENO + 1, &readfds, NULL, NULL, &timeout) > 0 && getchar() == '~') {
                  tcsetattr(STDIN_FILENO, TCSANOW, &oldattr);
                  return KEY_END; // Alternative END key sequence
               }
               break;
            }
         }
      }
      else {
         // Timeout - it's just ESC pressed alone
         tcsetattr(STDIN_FILENO, TCSANOW, &oldattr);
         return KEY_ESC;
      }
   }
   tcsetattr(STDIN_FILENO, TCSANOW, &oldattr);
   return ch; // Regular character
#endif
}

/////////////////////////////////////////////////////////////////////////////////
// Signal handler and exit wrapper - defined early so ALL code uses them
/////////////////////////////////////////////////////////////////////////////////
void c2SignalHandler(int sig) {
   fprintf(stderr, "\n*** CDL2 Runtime Error: Caught signal %d ***\n", sig);
   c2Backtrace();
   _Exit(sig);  // Use _Exit directly to avoid recursion
}

void c2InitTrace() {
   // Set up signal handlers to catch runtime errors
   signal(SIGSEGV, c2SignalHandler);  // Segmentation fault
   signal(SIGABRT, c2SignalHandler);  // Abort
   signal(SIGFPE, c2SignalHandler);  // Floating point exception
   signal(SIGILL, c2SignalHandler);  // Illegal instruction
#ifndef _WIN32
   signal(SIGBUS, c2SignalHandler);  // Bus error (POSIX)
#endif
}

static void c2Exit(int code) {
   static BOOL exiting = FALSE;
   if (!exiting && code != 0 && C2SP >= 0) {
      exiting = TRUE;
      fprintf(stderr, "\n*** CDL2 Program exiting with code %d ***\n", code);
      c2Backtrace();
   }
   _Exit(code);
}
/////////////////////////////////////////////////////////////////////////////////
// ANSI color codes for colored output
//////////////////////////////////////////////////////////////////////////////////
#define ANSI_COLOR_RESET "\x1b[0m"
char* ansi_fg(AnsiColor color) {
   static char buffer[8];
   if (color == RESET) {
      return ANSI_COLOR_RESET;
   }
   else {
      snprintf(buffer, sizeof(buffer), "\x1b[3%dm", color);
      return buffer;
   }
}
char* ansi_bg(AnsiColor color) {
   static char buffer[8];
   if (color == RESET) {
      return ANSI_COLOR_RESET;
   }
   else {
      snprintf(buffer, sizeof(buffer), "\x1b[4%dm", color);
      return buffer;
   }
}